<template>
  <div class="sql-console" aria-label="业务SQL控制台">
    <div class="sql-toolbar"><div class="sql-view-switch" role="group" aria-label="SQL工作区视图"><button type="button" :aria-pressed="view==='editor'" :class="{active:view==='editor'}" @click="view='editor'">编写 SQL</button><button type="button" :aria-pressed="view==='history'" :class="{active:view==='history'}" @click="view='history';loadHistory()">执行记录</button></div><span class="muted">本地共享 · 当前业务库</span></div>
    <div v-show="view==='editor'" class="sql-editor-workspace">
    <el-alert class="sql-warning" title="修改表结构或删除数据前，请确认已有备份" description="DDL 可能隐式提交，无法保证回滚；控制台不会自动备份数据。" type="warning" :closable="false" show-icon/>
    <details class="connection-note muted"><summary>支持的语句与连接说明</summary><p>支持当前业务库的单条查询、增删改及表结构 SQL，查询最多展示 500 条。智能体仍使用只读连接。</p><p>每次执行使用独立连接，不保留临时表和会话变量；TIMESTAMP 按 UTC 读取。</p></details>
    <label class="sql-label"><span>SQL 语句</span><el-input v-model="sql" type="textarea" :rows="6" :disabled="busy" placeholder="SELECT * FROM drugs LIMIT 20" aria-label="业务SQL语句"/></label>
    <div class="sql-submit-row"><label class="reason-label"><span>执行原因</span><el-input v-model="reason" :disabled="busy" maxlength="500" aria-label="SQL执行原因"/></label>
    <el-button type="primary" :disabled="!sql.trim() || !reason.trim()" :loading="busy" @click="preview">解析并预览</el-button></div>
    <section v-if="plan" class="sql-review" aria-label="SQL执行预览"><strong>{{ plan.kind }} · {{ plan.tables.join('、') }}</strong><pre>{{ plan.sql }}</pre><p>{{ plan.notice }}</p><p class="muted">预览展示语句与涉及的表；执行时使用数据库当时的数据，不保证与预览时相同。</p><el-checkbox v-model="confirmed" :disabled="busy">我已核对SQL和目标表，理解影响范围{{ plan.ddl?'及不可保证回滚的风险':'' }}</el-checkbox><div class="confirm-line"><el-input v-model="confirmationText" :disabled="busy" placeholder="输入 执行SQL 确认" aria-label="SQL确认文字"/><el-button :type="plan.kind==='SELECT'?'primary':'danger'" :disabled="!confirmed || confirmationText!=='执行SQL'" :loading="busy" @click="execute">执行SQL</el-button></div></section>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="operationId" class="muted">操作编号：{{ operationId }}。如状态不明，请核对执行记录和数据库，不要新建编号盲目重试。</p>
    <section v-if="result" class="sql-result" aria-label="SQL结果"><strong>{{ result.status==='completed'?'执行完成':'执行状态待核对' }}{{ result.affected_rows!==null?' · 影响 '+result.affected_rows+' 行':'' }}</strong><p v-if="result.truncated">结果超过500条，仅显示前500条。</p><el-table scrollbar-always-on class="app-resizable-table" v-if="result.columns.length" :data="result.rows.map(row=>Object.fromEntries(result.columns.map((c,i)=>[c,row[i]])))" border max-height="350"><el-table-column v-for="c in result.columns" :key="c" :prop="c" :label="c" min-width="140" show-overflow-tooltip/></el-table></section>
    </div>
    <section v-show="view==='history'" class="sql-history" aria-label="SQL执行记录"><div class="history-toolbar"><div><h2>SQL 执行记录</h2><p class="muted">最近 50 条 · 查看语句、执行状态和影响行数</p></div><el-button :disabled="busy" @click="loadHistory">刷新</el-button></div><p v-if="historyError" class="error" role="alert">{{ historyError }}</p><p v-if="!history.length && !historyError" class="muted">暂无 SQL 执行记录</p><article v-for="r in history" :key="r.operation_id"><strong>{{ statusName(r.status) }} · {{ r.kind }}</strong><span class="muted"> · {{ new Date(r.created_at).toLocaleString('zh-CN',{hour12:false}) }} · 本地共享操作者</span><pre>{{ r.sql_text }}</pre><p>原因：{{ r.reason }}</p><p v-if="r.result?.affected_rows!=null">影响 {{ r.result.affected_rows }} 行</p><small>{{ r.operation_id }}</small></article></section>
  </div>
</template>
<script setup>
import {onMounted,ref,watch} from 'vue'
import {previewBusinessSQL,executeBusinessSQL,getBusinessSQLHistory} from '../api'
const view=ref('editor'),sql=ref(''),reason=ref(''),plan=ref(null),confirmed=ref(false),confirmationText=ref(''),operationId=ref(''),busy=ref(false),error=ref(''),historyError=ref(''),result=ref(null),history=ref([])
watch([sql,reason],()=>{plan.value=null;confirmed.value=false;confirmationText.value='';operationId.value='';result.value=null},{flush:'sync'})
function statusName(status){return {completed:'已完成',failed:'已失败',executing:'已登记，待核对',uncertain:'结果不确定，需核对'}[status] || status}
async function preview(){busy.value=true;error.value='';plan.value=null;result.value=null;confirmed.value=false;confirmationText.value='';operationId.value='';try{plan.value=await previewBusinessSQL({sql:sql.value,reason:reason.value.trim()});operationId.value=crypto.randomUUID()}catch(e){error.value=e.message}finally{busy.value=false}}
async function execute(){busy.value=true;error.value='';try{result.value=await executeBusinessSQL({sql:sql.value,reason:reason.value.trim(),token:plan.value.token,operation_id:operationId.value,confirmed:true});plan.value=null}catch(e){error.value=e.message}finally{busy.value=false;await loadHistory()}}
async function loadHistory(){historyError.value='';try{history.value=(await getBusinessSQLHistory()).records}catch(e){historyError.value=e.message}}
onMounted(loadHistory)
</script>
<style scoped>
.sql-console{height:100%;min-height:0;overflow:auto;padding:4px 6px 16px 0;font-size:14px;line-height:1.6}.sql-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px;flex-wrap:wrap}.sql-view-switch{display:flex;gap:4px;padding:3px;border:1px solid var(--border);border-radius:8px;background:var(--bg)}.sql-view-switch button{border:0;border-radius:5px;padding:7px 14px;font:inherit;color:var(--text-secondary);background:transparent;cursor:pointer}.sql-view-switch button.active{background:var(--primary-soft);color:var(--primary);font-weight:600}.sql-view-switch button:focus-visible{outline:2px solid var(--primary);outline-offset:2px}.sql-editor-workspace>*+*{margin-top:16px}.sql-warning{height:auto;min-height:76px;align-items:flex-start;padding:14px 16px}.sql-warning :deep(.el-alert__content){min-width:0}.sql-warning :deep(.el-alert__title){font-size:14px;line-height:1.65;display:block}.sql-warning :deep(.el-alert__description){font-size:13px;line-height:1.65;margin:4px 0 0}.sql-warning :deep(.el-alert__icon){margin-top:3px;flex-shrink:0}.sql-label,.reason-label{display:flex;flex-direction:column;gap:8px}.sql-label>span,.reason-label>span{font-weight:500}.sql-console :deep(textarea){font-family:ui-monospace,SFMono-Regular,monospace;font-size:14px;line-height:1.65;min-height:190px}.sql-submit-row{display:flex;align-items:flex-end;gap:12px}.reason-label{flex:1;min-width:0}.sql-review,.sql-result{padding:16px;border:1px solid var(--border);border-radius:8px}.confirm-line{display:flex;gap:12px;margin-top:12px;flex-wrap:wrap}.confirm-line .el-input{max-width:260px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;background:var(--bg);padding:12px;border-radius:6px;margin:8px 0}.history-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px}.history-toolbar h2{font-size:17px;margin:0}.history-toolbar p{margin:5px 0}.sql-history article{border-bottom:1px solid var(--border);padding:16px 0}.sql-history p{margin:6px 0}.connection-note{font-size:13px}.connection-note summary{cursor:pointer;width:fit-content}.connection-note p{margin:7px 0}.muted,small{color:var(--text-secondary)}.error{color:var(--el-color-danger);margin:0}.sql-console :deep(.el-checkbox__label){white-space:normal}@media(max-width:650px){.sql-submit-row{align-items:stretch;flex-direction:column}.sql-submit-row>.el-button{align-self:flex-start}.sql-toolbar>span{font-size:13px}}
</style>
